PRAGMA foreign_keys=ON;
CREATE TABLE group_buy_campaigns(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,name TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',starts_at TEXT,ends_at TEXT,min_quantity INTEGER NOT NULL,limit_quantity INTEGER,member_only INTEGER NOT NULL DEFAULT 0);
CREATE TABLE group_buy_tiers(id TEXT PRIMARY KEY,campaign_id TEXT NOT NULL REFERENCES group_buy_campaigns(id),min_quantity INTEGER NOT NULL,unit_price_minor INTEGER NOT NULL);
CREATE TABLE group_buy_orders(id TEXT PRIMARY KEY,campaign_id TEXT NOT NULL REFERENCES group_buy_campaigns(id),order_id TEXT NOT NULL REFERENCES commerce_orders(id),quantity INTEGER NOT NULL,status TEXT NOT NULL);
CREATE TABLE affiliate_programs(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,name TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'disabled',attribution_days INTEGER NOT NULL DEFAULT 30,commission_rules_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE affiliate_partners(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,partner_id TEXT,status TEXT NOT NULL DEFAULT 'pending',display_name TEXT NOT NULL,UNIQUE(merchant_id,id));
CREATE TABLE affiliate_links(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,affiliate_partner_id TEXT NOT NULL,code TEXT NOT NULL UNIQUE,target_path TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE affiliate_clicks(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,link_id TEXT NOT NULL,visitor_hash TEXT NOT NULL,clicked_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE affiliate_attributions(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,affiliate_partner_id TEXT NOT NULL,customer_id TEXT,visitor_hash TEXT,first_seen_at TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE affiliate_commissions(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,affiliate_partner_id TEXT NOT NULL,order_id TEXT NOT NULL,amount_minor INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending',adjustment_minor INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(merchant_id,order_id,affiliate_partner_id));
CREATE TABLE affiliate_payouts(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,affiliate_partner_id TEXT NOT NULL,amount_minor INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'draft',paid_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE customer_wishlists(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,customer_id TEXT NOT NULL,UNIQUE(merchant_id,customer_id));
CREATE TABLE customer_wishlist_items(wishlist_id TEXT NOT NULL REFERENCES customer_wishlists(id),product_id TEXT NOT NULL REFERENCES commerce_products(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(wishlist_id,product_id));
CREATE TABLE restock_subscriptions(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,variant_id TEXT NOT NULL,customer_id TEXT,email_hash TEXT,status TEXT NOT NULL DEFAULT 'active',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE abandoned_carts(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,cart_id TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'detected',detected_at TEXT NOT NULL,stopped_at TEXT);
CREATE TABLE automation_campaigns(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,automation_type TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'disabled',channel TEXT NOT NULL,rules_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE automation_runs(id TEXT PRIMARY KEY,campaign_id TEXT NOT NULL REFERENCES automation_campaigns(id),subject_type TEXT NOT NULL,subject_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued',scheduled_at TEXT,completed_at TEXT,idempotency_key TEXT NOT NULL UNIQUE);
